//! Frozen addendum on `b64a6b96`. Lead, after reading `ca9789b0`: one
//! sandboxed run focuses the running app's pane, one take-over from outside
//! tmux makes the first app save, acknowledge and quit, a pane stamped
//! `@ae_console` neither writes nor reads the record, and `ae app --new`
//! writes no `app-view` and holds no record. The client's active pane is
//! the assertion that focus selected the pane.
//!
//! Private socket (`-S`), scratch `AE_HOME`, no ambient tmux. RED until the
//! run path does this. Do not edit this file to match an implementation.

#![allow(
    clippy::disallowed_methods,
    clippy::expect_used,
    reason = "the addendum owns a private tmux socket, a pty and scratch state"
)]

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Child, Command};
use std::thread;
use std::time::{Duration, Instant};

use super::cli::OwnedScratch;
use super::phase2::run_tmux;
use ae::app::handover;
use ae::app::instance;

const STAMP: &str = "0199c0de-cccc-4890-abcd-ef0123456789";
const WAIT: Duration = Duration::from_secs(20);

struct Server {
    root: OwnedScratch,
    sock: PathBuf,
}

impl Server {
    fn new(tag: &str) -> Self {
        let root = OwnedScratch::root("asg", tag);
        let sock = root.path().join("sock");
        let server = Self { root, sock };
        fs::write(server.root.path().join("config"), "[workspace]\n").expect("config");
        // The tmux session is named `app`. `ae app` with no operand takes that
        // name as its home and refuses an unrecorded one before the singleton
        // (`ae app: no session named app`). The directory name is what
        // `console::locate` matches. This does not change that refusal.
        let session = server.path().join("sessions").join("app");
        fs::create_dir_all(&session).expect("recorded home");
        fs::write(
            session.join("meta"),
            format!(
                "session=app\nmode=local\nsession_id={STAMP}\nlayout=lead-pair\ntmux_server_kind=socket\ntmux_server={}\n",
                server.sock.display()
            ),
        )
        .expect("recorded home meta");
        server
    }

    fn path(&self) -> &Path {
        self.root.path()
    }

    fn tmux(&self, tail: &[&str]) -> String {
        let mut args = vec![
            "-S".to_owned(),
            self.sock.display().to_string(),
            "-f".to_owned(),
            "/dev/null".to_owned(),
        ];
        args.extend(tail.iter().map(|arg| (*arg).to_owned()));
        let (ok, out) = run_tmux(&args, self.path());
        assert!(ok, "tmux {tail:?}: {out}");
        out
    }

    fn launch(&self, session: &str, command: &str) {
        self.tmux(&[
            "new-session",
            "-d",
            "-s",
            session,
            "-x",
            "80",
            "-y",
            "24",
            command,
        ]);
        self.tmux(&["set-option", "-g", "remain-on-exit", "on"]);
    }

    fn pane(&self, target: &str) -> String {
        self.tmux(&["display-message", "-p", "-t", target, "#{pane_id}"])
            .trim()
            .to_owned()
    }

    fn pane_pid(&self, target: &str) -> u32 {
        self.tmux(&["display-message", "-p", "-t", target, "#{pane_pid}"])
            .trim()
            .parse()
            .expect("pane pid")
    }

    fn screen(&self, target: &str) -> String {
        self.tmux(&["capture-pane", "-p", "-t", target])
    }

    fn wait_paint(&self, target: &str) {
        let until = Instant::now() + WAIT;
        loop {
            let screen = self.screen(target);
            if screen.contains("Agents") || screen.contains("No sessions") {
                return;
            }
            assert!(Instant::now() < until, "the app did not paint:\n{screen}");
            thread::sleep(Duration::from_millis(50));
        }
    }

    fn wait_record(&self) -> instance::Instance {
        let path = self.path().join(instance::INSTANCE);
        let until = Instant::now() + WAIT;
        loop {
            if let Ok(bytes) = fs::read(&path)
                && let Some(record) = instance::parse_instance(&bytes)
            {
                return record;
            }
            assert!(
                Instant::now() < until,
                "the governed app did not write {}",
                instance::INSTANCE
            );
            thread::sleep(Duration::from_millis(50));
        }
    }
}

impl Drop for Server {
    fn drop(&mut self) {
        let args = vec![
            "-S".to_owned(),
            self.sock.display().to_string(),
            "-f".to_owned(),
            "/dev/null".to_owned(),
            "kill-server".to_owned(),
        ];
        let _ = run_tmux(&args, self.path());
    }
}

fn quote(path: &Path) -> String {
    format!("'{}'", path.display().to_string().replace('\'', "'\\''"))
}

fn governed(server: &Server, extra: &str) -> String {
    format!(
        "env TERM=xterm-256color AE_HOME={root} CONFIG_FILE={config} HOME={root} AE_TMUX_SERVER_KIND=socket AE_TMUX_SERVER={sock} {bin} app {extra}",
        root = quote(server.path()),
        config = quote(&server.path().join("config")),
        sock = quote(&server.sock),
        bin = quote(Path::new(env!("CARGO_BIN_EXE_ae"))),
        extra = extra,
    )
}

/// A second `ae app` with no `TMUX`, on a real tty, so the path is take-over
/// and not the no-terminal refusal.
struct Outside {
    child: Child,
    pidfile: PathBuf,
}

impl Outside {
    fn spawn(server: &Server) -> Self {
        let pidfile = server.path().join("outside.pid");
        let script = format!(
            "echo $$ > {pid}; exec env -u TMUX -u TMUX_PANE TERM=xterm-256color AE_HOME={root} CONFIG_FILE={config} HOME={root} {bin} app",
            pid = quote(&pidfile),
            root = quote(server.path()),
            config = quote(&server.path().join("config")),
            bin = quote(Path::new(env!("CARGO_BIN_EXE_ae"))),
        );
        let mut command = Command::new("script");
        command
            .env_remove("TMUX")
            .env_remove("TMUX_PANE")
            .current_dir(server.path());
        #[cfg(target_os = "macos")]
        command
            .arg("-q")
            .arg("/dev/null")
            .arg("sh")
            .arg("-c")
            .arg(script);
        #[cfg(not(target_os = "macos"))]
        command
            .arg("-q")
            .arg("-e")
            .arg("-c")
            .arg(script)
            .arg("/dev/null");
        let child = command.spawn().expect("script can allocate a tty");
        Self { child, pidfile }
    }
}

impl Drop for Outside {
    fn drop(&mut self) {
        if let Ok(text) = fs::read_to_string(&self.pidfile)
            && let Ok(pid) = text.trim().parse::<u32>()
        {
            let _ = Command::new("kill").arg(pid.to_string()).status();
        }
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn absent(server: &Server, name: &str) -> bool {
    !server.path().join(name).exists()
}

#[test]
fn a_second_app_on_the_same_server_focuses_the_running_pane() {
    let server = Server::new("focus");
    server.launch("app", &governed(&server, ""));
    let app_pane = server.pane("app");
    let record = server.wait_record();
    server.wait_paint("app");
    assert_eq!(
        record.pid,
        server.pane_pid("app"),
        "the record names the running app"
    );

    let caller = server
        .tmux(&[
            "new-window",
            "-d",
            "-n",
            "call",
            "-t",
            "app",
            "-P",
            "-F",
            "#{pane_id}",
            "sleep 120",
        ])
        .trim()
        .to_owned();
    let attach = format!(
        "env -u TMUX -u TMUX_PANE tmux -u -S {} attach-session -t app:call",
        quote(&server.sock)
    );
    server.launch("view", &attach);
    let client = wait_client(&server, &caller);
    let out = server.path().join("focus-out");
    let err = server.path().join("focus-err");
    let status = server.path().join("focus-status");
    let command = format!(
        "{run} > {out} 2> {err}; echo $? > {status}",
        run = governed(&server, ""),
        out = quote(&out),
        err = quote(&err),
        status = quote(&status),
    );
    server.tmux(&["respawn-pane", "-k", "-t", &caller, &command]);

    let until = Instant::now() + WAIT;
    loop {
        if fs::read_to_string(&status).is_ok_and(|text| !text.trim().is_empty()) {
            break;
        }
        assert!(
            Instant::now() < until,
            "the second app did not exit; stderr {:?}",
            fs::read_to_string(&err).ok()
        );
        thread::sleep(Duration::from_millis(50));
    }
    assert_eq!(
        fs::read_to_string(&status).expect("status").trim(),
        "0",
        "focus exits 0: {:?}",
        fs::read_to_string(&err).ok()
    );
    assert_eq!(fs::read(&out).expect("stdout"), b"", "focus starts no TUI");
    assert_eq!(
        fs::read(&err).expect("stderr"),
        instance::focused_line(&app_pane, None).into_bytes(),
        "one line, and the named home was absent"
    );
    let now = server.tmux(&["list-clients", "-F", "#{client_name}|#{pane_id}"]);
    assert!(
        now.lines()
            .any(|line| line == format!("{client}|{app_pane}")),
        "the caller's active pane is the running app: {now}"
    );
    assert_eq!(
        server.pane_pid("app"),
        record.pid,
        "the first app is still the instance"
    );
}

fn wait_client(server: &Server, pane: &str) -> String {
    let until = Instant::now() + WAIT;
    loop {
        let listed = server.tmux(&["list-clients", "-F", "#{client_name}|#{pane_id}"]);
        if let Some(name) = listed.lines().find_map(|line| {
            let (name, at) = line.split_once('|')?;
            (at == pane).then_some(name.to_owned())
        }) {
            return name;
        }
        assert!(
            Instant::now() < until,
            "no client is attached to {pane}: {listed}"
        );
        thread::sleep(Duration::from_millis(50));
    }
}

#[test]
fn an_app_outside_tmux_takes_over_and_the_first_saves_and_quits() {
    let server = Server::new("take");
    server.launch("app", &governed(&server, ""));
    let app_pane = server.pane("app");
    let record = server.wait_record();
    server.wait_paint("app");
    assert_eq!(record.pid, server.pane_pid("app"));
    let _outside = Outside::spawn(&server);

    let ack = server.path().join(instance::ACK);
    let view = server.path().join(handover::FILE);
    let until = Instant::now() + WAIT;
    loop {
        let saved = fs::read(&view).ok();
        let noted = fs::read(&ack).ok();
        let listed = server.tmux(&[
            "list-panes",
            "-t",
            "app",
            "-F",
            "#{pane_id}|#{pane_dead}|#{pane_dead_status}",
        ]);
        let quit = listed.lines().any(|line| {
            let mut fields = line.split('|');
            fields.next() == Some(app_pane.as_str())
                && fields.next() == Some("1")
                && fields.next() == Some("0")
        });
        if quit && saved.is_some() && noted.is_some() {
            let bytes = saved.expect("view");
            assert!(
                handover::parse_file(&bytes).is_some(),
                "app-view is the durable view: {bytes:?}"
            );
            let parsed = instance::parse_ack(&noted.expect("ack")).expect("the acknowledgement");
            assert_eq!(parsed.nonce.len(), instance::NONCE_LEN);
            assert!(
                absent(&server, instance::REQUEST),
                "the requester removes its request after the acknowledgement"
            );
            return;
        }
        assert!(
            Instant::now() < until,
            "the first app did not save, acknowledge and quit: panes {listed}; view {}; ack {}",
            view.exists(),
            ack.exists()
        );
        thread::sleep(Duration::from_millis(50));
    }
}

#[test]
fn a_stamped_chat_window_neither_writes_nor_reads_the_instance_record() {
    let server = Server::new("stamp");
    server.launch("app", &governed(&server, ""));
    let first = server.pane("app");
    let record = server.wait_record();
    server.wait_paint("app");
    assert_eq!(record.pid, server.pane_pid("app"));

    let stamped = server
        .tmux(&[
            "new-window",
            "-d",
            "-n",
            "chat",
            "-t",
            "app",
            "-P",
            "-F",
            "#{pane_id}",
            "sleep 120",
        ])
        .trim()
        .to_owned();
    server.tmux(&["set-option", "-p", "-t", &stamped, "@ae_console", STAMP]);
    server.tmux(&["respawn-pane", "-k", "-t", &stamped, &governed(&server, "")]);
    server.wait_paint(&stamped);

    let again = fs::read(server.path().join(instance::INSTANCE)).expect("record stays");
    let held = instance::parse_instance(&again).expect("record still parses");
    assert_eq!(
        held.pid, record.pid,
        "the stamped app did not write the record"
    );
    assert_eq!(
        server.pane_pid(&first),
        record.pid,
        "the stamped app did not take the running app's pane"
    );
    let dead = server.tmux(&["display-message", "-p", "-t", &stamped, "#{pane_dead}"]);
    assert_eq!(
        dead.trim(),
        "0",
        "the stamped app is a TUI, not a focus exit"
    );
}

#[test]
fn a_fresh_app_writes_no_view_and_holds_no_record() {
    let server = Server::new("fresh");
    server.launch("app", &governed(&server, "--new"));
    server.wait_paint("app");
    assert!(absent(&server, instance::LOCK), "no lock");
    assert!(absent(&server, instance::INSTANCE), "no record");
    assert!(absent(&server, handover::FILE), "no view yet");
    server.tmux(&["send-keys", "-t", "app", "X"]);
    let until = Instant::now() + Duration::from_secs(5);
    while Instant::now() < until {
        assert!(absent(&server, handover::FILE), "--new wrote app-view");
        assert!(absent(&server, instance::LOCK), "--new took the lock");
        assert!(
            absent(&server, instance::INSTANCE),
            "--new wrote the record"
        );
        thread::sleep(Duration::from_millis(100));
    }
    let dead = server.tmux(&["display-message", "-p", "-t", "app", "#{pane_dead}"]);
    assert_eq!(dead.trim(), "0", "--new is still the app");
}
